// IDE side of inline completion: most requests must die before they cost GPU time.
const DEBOUNCE_MS = 75;                  // lower = snappier, but more requests
const cache = new Map<string, string>(); // users backspace and retype constantly
let timer: ReturnType<typeof setTimeout> | undefined;
let inflight: AbortController | undefined;

export function onKeystroke(doc: TextDoc, cursor: number) {
  clearTimeout(timer);
  inflight?.abort();                     // the old suggestion is already stale
  timer = setTimeout(() => void complete(doc, cursor), DEBOUNCE_MS);
}

async function complete(doc: TextDoc, cursor: number) {
  const prefix = doc.text.slice(Math.max(0, cursor - 6_000), cursor);
  const suffix = doc.text.slice(cursor, cursor + 2_000); // so it won't re-close brackets
  const key = hash(prefix.slice(-400) + "|" + suffix.slice(0, 200));
  const hit = cache.get(key);
  if (hit !== undefined) return showGhostText(hit);
  inflight = new AbortController();
  try {
    const res = await fetch(COMPLETE_URL, {
      method: "POST", signal: inflight.signal, // server sees the abort, stops decoding
      body: JSON.stringify({
        prefix, suffix,
        snippets: similarSnippets(doc, 3), // open tabs and recent edits
        max_tokens: 64, stop: ["\n\n"],
      }),
    });
    const { text } = await res.json();
    cache.set(key, text);
    showGhostText(text);
  } catch (e) {
    if ((e as Error).name !== "AbortError") reportError(e);
  }
}
